function confirmArchiveProduct(id){const item=stocks.find(x=>x.id===id);if(!item)return;pendingDeleteStockId=id;el.deleteStockText.textContent=`${item.name} stok takibinden kaldırılacak. Kritik, tükenen ve tüm ürünler listelerinde artık görünmeyecek. Geçmiş hareket kayıtları korunacak.`;el.deleteStockDialog.returnValue="cancel";el.deleteStockDialog.showModal()}
async function archiveProduct(id){const item=stocks.find(x=>x.id===id);if(!item)return;pendingDeleteStockId="";try{await updateDoc(doc(stocksCol,id),{active:false,automaticDeduction:false,barcode:"",deletedAt:serverTimestamp(),deletedBy:auth.currentUser.uid,updatedAt:serverTimestamp()});if(el.historyDialog.open)el.historyDialog.close();if(el.productsDialog.open)renderProductManager();setStockFilter("all");show(`${item.name} stok takibinden silindi.`)}catch(error){console.error(error);show("Ürün stok takibinden silinemedi.")}}

function openEditProduct(){const item=stocks.find(x=>x.id===historyStockId);if(!item)return;const menuItem=catalog.items.find(x=>x.id===item.linkedMenuItemId);el.editProductId.value=item.id;el.editProductTitle.textContent=`${item.name} Düzenle`;el.editProductName.value=item.name;el.editProductBrand.value=item.brand;el.editProductBarcode.value=item.barcode;el.editUnitsPerPackage.value=item.unitsPerPackage;el.editWarningThreshold.value=item.warningThreshold;el.editStockTrackingEnabled.checked=item.stockTrackingEnabled;el.editProductLinkInfo.textContent=!item.stockTrackingEnabled?"Stok takibi kapalı; satış düşümü ve stok uyarıları çalışmaz.":menuItem?`Menü bağlantısı: ${menuItem.name} • Adisyonda satıldığında stoktan otomatik düşer.`:"Bu ürün menüye bağlı değil; stok hareketleri elle takip edilir.";el.editProductDialog.showModal();setTimeout(()=>el.editProductName.select(),80)}
async function saveProductEdit(e){e.preventDefault();const item=stocks.find(x=>x.id===el.editProductId.value),name=el.editProductName.value.trim(),brand=el.editProductBrand.value.trim(),barcode=el.editProductBarcode.value.replace(/\s/g,""),unitsPerPackage=Math.max(1,num(el.editUnitsPerPackage.value)),warningThreshold=Math.max(0,num(el.editWarningThreshold.value)),stockTrackingEnabled=el.editStockTrackingEnabled.checked;if(!item||!name)return show("Ürün adını yazın.");if(barcode&&barcode.length<4)return show("Barkod numarasını kontrol edin.");if(barcode&&stocks.some(x=>x.active&&x.id!==item.id&&x.barcode===barcode))return show("Bu barkod başka bir stok ürününde kayıtlı.");try{await updateDoc(doc(stocksCol,item.id),{name,brand,barcode,unitsPerPackage,warningThreshold,stockTrackingEnabled,automaticDeduction:stockTrackingEnabled&&!!item.linkedMenuItemId,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});el.editProductDialog.close();el.historyDialog.close();show(stockTrackingEnabled?"Ürün bilgileri ve stok takibi güncellendi.":"Ürün bilgileri güncellendi; stok takibi kapatıldı.")}catch(error){console.error(error);show("Ürün bilgileri güncellenemedi.")}}

function openEntry(id){const item=stocks.find(x=>x.id===id);if(!item)return;el.entryStockId.value=id;el.entryTitle.textContent=`${item.name} Stok Girişi`;el.packageCount.value="";el.entryUnitsPerPackage.value=item.unitsPerPackage;el.purchaseTotal.value="";el.addCashExpense.checked=false;el.cashExpenseAccount.value="cash";el.cashExpenseAccountLabel.hidden=true;el.entryDate.value=today();el.entryNote.value="";renderCostPreview();el.entryDialog.showModal()}
function renderCostPreview(){const count=num(el.packageCount.value),perPackage=num(el.entryUnitsPerPackage.value),totalUnits=count*perPackage,packageCost=num(el.purchaseTotal.value),totalPaid=count*packageCost,unitCost=perPackage>0?packageCost/perPackage:0;el.costPreview.innerHTML=`<span>Toplam Adet: <b>${formatNumber(totalUnits)}</b> • Toplam alış: <b>${packageCost>0?money(totalPaid):"—"}</b></span><strong>Birim maliyet: ${totalUnits>0&&packageCost>0?money(unitCost):"—"}</strong>`}
async function saveEntry(e){e.preventDefault();if(busy)return;const item=stocks.find(x=>x.id===el.entryStockId.value),packageCount=num(el.packageCount.value),unitsPerPackage=num(el.entryUnitsPerPackage.value),packageCost=num(el.purchaseTotal.value),purchaseTotal=packageCount*packageCost,amount=packageCount*unitsPerPackage,addExpense=el.addCashExpense.checked;if(!item||packageCount<=0||unitsPerPackage<=0||packageCost<=0)return show("Koli sayısı, koli içi adet ve bir koli alış fiyatını eksiksiz girin.");busy=true;try{const itemRef=doc(stocksCol,item.id),moveRef=doc(movesCol),cashRef=doc(cashMovesCol),createdAtMs=Date.now();await runTransaction(db,async tx=>{const snap=await tx.get(itemRef);if(!snap.exists())throw new Error("missing");const fresh=normalizeStock(snap.id,snap.data());if(fresh.quantity>0&&fresh.unitCost<=0)throw new Error("missing-cost");const result=fresh.quantity+amount,oldValue=fresh.quantity*fresh.unitCost,unitCost=result>0?(oldValue+purchaseTotal)/result:packageCost/unitsPerPackage;tx.update(itemRef,{quantity:result,unitsPerPackage,lastPurchaseTotal:purchaseTotal,unitCost,purchasePrice:packageCost,purchasePriceBasis:"package",purchaseDate:el.entryDate.value,updatedAt:serverTimestamp()});tx.set(moveRef,{stockItemId:item.id,linkedMenuItemId:item.linkedMenuItemId,stockName:item.name,type:"in",packageCount,unitsPerPackage,amount,enteredAmount:packageCount,enteredUnit:"koli",purchasePrice:packageCost,purchasePriceBasis:"package",purchaseTotal,purchaseUnitCost:packageCost/unitsPerPackage,unitCost,previousUnitCost:fresh.unitCost,previousQuantity:fresh.quantity,resultingQuantity:result,unit:item.unit,operationDate:el.entryDate.value,note:el.entryNote.value.trim(),cashMovementId:addExpense?cashRef.id:"",createdAtMs,createdAt:serverTimestamp(),createdBy:auth.currentUser.uid});if(addExpense)tx.set(cashRef,{type:"expense",amount:purchaseTotal,account:el.cashExpenseAccount.value,fromAccount:"",toAccount:"",category:"Toptancı / Ürün Alımı",description:`${item.name} stok alımı`,businessDate:el.entryDate.value,automatic:true,source:"stock-purchase",sourceId:moveRef.id,createdAtMs,updatedAtMs:createdAtMs,createdAt:serverTimestamp(),updatedAt:serverTimestamp(),createdBy:auth.currentUser.uid})});el.entryDialog.close();show(addExpense?`${formatNumber(amount)} Adet stoka, ${money(purchaseTotal)} alış gideri kasaya eklendi.`:`${formatNumber(amount)} Adet stoka eklendi.`)}catch(error){console.error(error);show(error.message==="missing-cost"?"Önce bu ürünün mevcut stok alış fiyatını Sermaye bölümünden tamamlayın.":"Stok ve kasa kaydı tamamlanamadı.")}finally{busy=false}}

function openAdjust(id){const item=stocks.find(x=>x.id===id);if(!item)return;el.adjustStockId.value=id;el.adjustTitle.textContent=`${item.name} Stok Düzeltme`;el.adjustAmount.value="";el.adjustDate.value=today();el.adjustNote.value="";el.adjustForm.elements.adjustType.value="out";renderAdjustPreview();el.adjustDialog.showModal()}
function renderAdjustPreview(){const item=stocks.find(x=>x.id===el.adjustStockId.value);if(!item)return;const type=el.adjustForm.elements.adjustType.value,amount=num(el.adjustAmount.value),result=type==="out"?item.quantity-amount:amount;el.adjustAmountLabel.textContent=type==="out"?"Düşülecek Adet":"Yeni toplam Adet";el.adjustPreview.textContent=`Mevcut: ${formatNumber(item.quantity)} → Yeni: ${formatNumber(result)}`;el.adjustPreview.style.color=result<0?"#a22a32":""}
async function saveAdjustment(e){e.preventDefault();if(busy)return;const item=stocks.find(x=>x.id===el.adjustStockId.value),type=el.adjustForm.elements.adjustType.value,amount=num(el.adjustAmount.value);if(!item||amount<0)return;busy=true;try{const itemRef=doc(stocksCol,item.id),moveRef=doc(movesCol);await runTransaction(db,async tx=>{const snap=await tx.get(itemRef);if(!snap.exists())throw new Error("missing");const fresh=normalizeStock(snap.id,snap.data()),result=type==="out"?fresh.quantity-amount:amount;if(result<0)throw new Error("insufficient");tx.update(itemRef,{quantity:result,updatedAt:serverTimestamp()});tx.set(moveRef,{stockItemId:item.id,linkedMenuItemId:item.linkedMenuItemId,stockName:item.name,type,amount,previousQuantity:fresh.quantity,resultingQuantity:result,unit:item.unit,operationDate:el.adjustDate.value,note:el.adjustNote.value.trim(),createdAt:serverTimestamp(),createdBy:auth.currentUser.uid})});el.adjustDialog.close();show("Stok İşlemi kaydedildi.")}catch(error){console.error(error);show(error.message==="insufficient"?"Stok miktarı sıfırın altına düşemez.":"İşlem kaydedilemedi.")}finally{busy=false}}

function renderMovements(){const items=movements.slice(0,50);el.movementList.innerHTML=items.map(x=>{const incoming=x.type==="in"||x.type==="initial",sign=incoming?"+":x.type==="out"||x.type==="sale"?"−":"=",label=x.type==="in"?"Stok Girişi":x.type==="out"?"Stoktan Düşüm":x.type==="sale"?"Adisyon Satışı":x.type==="initial"?"İlk Stok":"Sayım Düzeltmesi",purchase=num(x.purchaseTotal)||(x.purchasePriceBasis==="total"?num(x.purchasePrice):0);return`<article class="movement-item"><span class="movement-icon ${incoming?"":"out"}"><i class="fa-solid ${incoming?"fa-plus":x.type==="set"?"fa-pen":"fa-minus"}"></i></span><div class="movement-copy"><strong>${esc(x.stockName||"Stok")}</strong><span>${label} • ${formatDate(x.operationDate)}${num(x.packageCount)>0?` • ${formatNumber(x.packageCount)} Koli`:""}${purchase>0?` • ${money(purchase)} Alış`:""}${x.note?` • ${esc(x.note)}`:""}</span></div><div class="movement-amount">${sign}${formatNumber(x.amount)} ${esc(displayUnit(x.unit||""))}<span class="movement-result">Kalan: ${formatNumber(x.resultingQuantity)}</span></div></article>`}).join("");el.movementEmpty.hidden=items.length>0}

async function openHistory(id){const item=stocks.find(x=>x.id===id);if(!item)return;historyStockId=id;const menuItem=catalog.items.find(x=>x.id===item.linkedMenuItemId),menuPrice=num(menuItem?.price);el.historyLinkButton.hidden=false;el.historyLinkButton.innerHTML=`<i class="fa-solid ${menuItem?"fa-link":"fa-link-slash"}"></i> Menü Bağlantısı`;el.historyTitle.textContent=item.name;el.historySummary.innerHTML=`<span>Mevcut stok<b>${formatNumber(item.quantity)} ${esc(displayUnit(item.unit))}</b></span><span>Alış fiyatı<b>${item.unitCost?`${money(item.unitCost)} / adet`:"—"}</b></span><span>Menü bağlantısı<b>${menuItem?esc(menuItem.name):"Bağlı değil"}</b></span><span>Menü fiyatı<b>${menuItem?(menuPrice?money(menuPrice):"Fiyat yok"):"—"}</b></span><span>Son alım<b>${item.lastPurchaseTotal?money(item.lastPurchaseTotal):"—"}</b></span><span>Koli içi<b>${formatNumber(item.unitsPerPackage)} ${esc(displayUnit(item.unit))}</b></span><span>Barkod<b>${esc(item.barcode||"Tanımlı değil")}</b></span>`;el.historyList.innerHTML='<p class="empty-copy"><i class="fa-solid fa-circle-notch fa-spin"></i> Hareketler yükleniyor…</p>';el.historyEmpty.hidden=true;el.historyDialog.showModal();try{const snap=await getDocs(query(movesCol,where("stockItemId","==",id),limit(300))),items=snap.docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>movementTime(b)-movementTime(a));renderProductHistory(items)}catch(error){console.error(error);el.historyList.innerHTML="";el.historyEmpty.textContent="Stok hareketleri yüklenemedi.";el.historyEmpty.hidden=false}}
function openLinkMenu(){const item=stocks.find(x=>x.id===historyStockId);if(!item)return;const used=new Set(stocks.filter(x=>x.active&&x.id!==item.id&&x.linkedMenuItemId).map(x=>x.linkedMenuItemId)),available=catalog.items.filter(x=>x.available!==false&&!used.has(x.id)).sort((a,b)=>String(a.name).localeCompare(String(b.name),"tr")),current=catalog.items.find(x=>x.id===item.linkedMenuItemId);el.linkMenuText.textContent=current?`${item.name} şu anda ${current.name} ürününe bağlı. Bağlantıyı değiştirebilir veya kaldırabilirsiniz.`:`${item.name} menüye bağlı değil. İsterseniz bir menü ürünü seçerek otomatik stok düşümünü açabilirsiniz.`;el.linkMenuProduct.innerHTML='<option value="">Bağlı değil — otomatik düşmesin</option>'+available.map(x=>`<option value="${esc(x.id)}">${esc(x.name)}</option>`).join("");el.linkMenuProduct.value=current?.id||"";el.linkMenuDialog.showModal();setTimeout(()=>el.linkMenuProduct.focus(),80)}
async function saveMenuLink(e){e.preventDefault();const item=stocks.find(x=>x.id===historyStockId),menuItem=catalog.items.find(x=>x.id===el.linkMenuProduct.value);if(!item)return;try{await updateDoc(doc(stocksCol,item.id),{linkedMenuItemId:menuItem?.id||"",automaticDeduction:item.stockTrackingEnabled&&!!menuItem,deductionAmount:menuItem?1:0,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});el.linkMenuDialog.close();el.historyDialog.close();show(menuItem?`${item.name}, ${menuItem.name} ürününe bağlandı${item.stockTrackingEnabled?".":"; stok takibi kapalı olduğu için otomatik düşüm yapılmaz."}`:`${item.name} menü bağlantısı kaldırıldı; artık otomatik düşmeyecek.`)}catch(error){console.error(error);show("Menü bağlantısı kaydedilemedi.")}}
function renderProductHistory(items){el.historyEmpty.hidden=items.length>0;el.historyList.innerHTML=items.map(x=>{const incoming=x.type==="in"||x.type==="initial",label=movementLabel(x.type),sign=incoming?"+":x.type==="set"?"=":"−",purchase=num(x.purchaseTotal)||(x.purchasePriceBasis==="total"?num(x.purchasePrice):0),who=userNames.get(x.createdBy)||shortUser(x.createdBy);return`<article class="history-row"><span class="movement-icon ${incoming?"":"out"}"><i class="fa-solid ${incoming?"fa-plus":x.type==="set"?"fa-pen":"fa-minus"}"></i></span><div class="history-copy"><strong>${label} • ${formatMovementDate(x)}</strong><span>${esc(who)}${x.note?` • ${esc(x.note)}`:""}${purchase?` • Alış ${money(purchase)}`:""}</span></div><div class="history-values">${sign}${formatNumber(x.amount)} ${esc(displayUnit(x.unit||"adet"))}<small>${formatNumber(x.previousQuantity)} → ${formatNumber(x.resultingQuantity)}</small></div></article>`}).join("")}
function movementLabel(type){return type==="in"?"Stok Girişi":type==="out"?"Stoktan Düşüm":type==="sale"?"Adisyon Satışı":type==="initial"?"İlk Stok":"Sayım Düzeltmesi"}
function movementTime(x){return num(x.createdAtMs)||timestamp(x.createdAt)||Date.parse(x.operationDate||"")||0}
function formatMovementDate(x){const ms=movementTime(x);return ms?new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"numeric",hour:"2-digit",minute:"2-digit",timeZone:"Europe/Istanbul"}).format(new Date(ms)):formatDate(x.operationDate)}
function shortUser(uid){return uid?`Kullanıcı • ${String(uid).slice(0,6)}`:"Sistem"}
async function loadUserNames(){try{const snap=await getDocs(collection(db,"staffUsers"));snap.docs.forEach(d=>userNames.set(d.id,d.data().displayName||"Yönetim kullanıcısı"))}catch(error){console.info("Kullanıcı adları sınırlı erişimle gösteriliyor.")}}

async function openBarcode(mode="add"){barcodeMode=mode;try{cameraFacing=localStorage.getItem("fatih-stock-camera-facing")==="user"?"user":"environment";cameraDeviceId=localStorage.getItem("fatih-barcode-camera-device")||""}catch{cameraFacing="environment";cameraDeviceId=""}el.cameraDeviceRow.hidden=true;pendingBarcode="";el.barcodeInput.value="";el.barcodeMatch.hidden=true;el.saveBarcodeButton.hidden=mode==="new";el.barcodeProduct.closest("label").hidden=mode==="new";el.barcodeKicker.textContent=mode==="search"?"Ürün sorgulama":mode==="new"?"Yeni stok ürünü":"Hızlı stok girişi";el.barcodeTitle.textContent=mode==="search"?"Barkodlu Ürün Ara":mode==="new"?"Barkodla Ürün Ekle":"Barkodla Stok Girişi";el.cameraStatus.textContent="Kamera hazırlanıyor…";el.barcodeDialog.showModal();setTimeout(()=>el.barcodeInput.focus(),100);await startCamera()}
async function startCamera(){stopCamera();const session=cameraSession;if(!navigator.mediaDevices?.getUserMedia){el.cameraStatus.textContent="Bu cihazda kamera kullanılamıyor. Barkodu elle girin.";return}const video={width:{ideal:1280},height:{ideal:720}};if(cameraDeviceId)video.deviceId={exact:cameraDeviceId};else video.facingMode={ideal:cameraFacing};let stream;try{stream=await navigator.mediaDevices.getUserMedia({video,audio:false})}catch(error){if(cameraDeviceId){cameraDeviceId="";forgetCameraDevice();return startCamera()}console.error(error);el.cameraStatus.textContent="Kamera açılamadı. İzin verin veya barkodu elle girin.";return}if(session!==cameraSession){stream.getTracks().forEach(track=>track.stop());return}cameraStream=stream;try{el.barcodeVideo.srcObject=cameraStream;await el.barcodeVideo.play();const track=cameraStream.getVideoTracks()[0];await tuneBarcodeCamera(track);await populateCameraDevices(track.getSettings?.().deviceId||"");if("BarcodeDetector"in window){el.cameraStatus.textContent=`${cameraFacing==="environment"?"Arka":"Ön"} kamera • 1x • Barkodu ortalayın.`;scanBarcode(session)}else el.cameraStatus.textContent="Otomatik okuma desteklenmiyor. Barkodu elle girin."}catch(error){console.error(error);el.cameraStatus.textContent="Kamera hazırlanamadı. Barkodu elle girebilirsiniz."}}
async function tuneBarcodeCamera(track){if(!track?.getCapabilities||!track.applyConstraints)return;const caps=track.getCapabilities();try{if(caps.zoom){const zoom=Math.min(caps.zoom.max,Math.max(caps.zoom.min,1));await track.applyConstraints({advanced:[{zoom}]})}}catch{}try{if(Array.isArray(caps.focusMode)&&caps.focusMode.includes("continuous"))await track.applyConstraints({advanced:[{focusMode:"continuous"}]})}catch{}}
async function populateCameraDevices(currentId){try{const devices=(await navigator.mediaDevices.enumerateDevices()).filter(x=>x.kind==="videoinput");el.cameraSettingsButton.hidden=devices.length<2;if(devices.length<2)el.cameraDeviceRow.hidden=true;el.cameraDeviceSelect.innerHTML=devices.map((x,i)=>`<option value="${esc(x.deviceId)}">${esc(cameraLabel(x.label,i))}</option>`).join("");if(currentId)el.cameraDeviceSelect.value=currentId}catch{el.cameraSettingsButton.hidden=true;el.cameraDeviceRow.hidden=true}}
function cameraLabel(label,index){const value=String(label||"").trim();return`Kamera ${index+1}${value?` • ${value}`:""}`}
async function selectCameraDevice(){cameraDeviceId=el.cameraDeviceSelect.value;el.cameraDeviceRow.hidden=true;try{localStorage.setItem("fatih-barcode-camera-device",cameraDeviceId)}catch{}el.cameraStatus.textContent="Seçilen kamera açılıyor…";await startCamera()}
async function switchCamera(){cameraFacing=cameraFacing==="environment"?"user":"environment";cameraDeviceId="";forgetCameraDevice();try{localStorage.setItem("fatih-stock-camera-facing",cameraFacing)}catch{}el.switchCameraButton.disabled=true;el.cameraStatus.textContent="Kamera değiştiriliyor…";await startCamera();el.switchCameraButton.disabled=false}
function forgetCameraDevice(){try{localStorage.removeItem("fatih-barcode-camera-device")}catch{}}
async function scanBarcode(session=cameraSession){if(session!==cameraSession||!cameraStream||el.barcodeDialog.open===false)return;try{const detector=new BarcodeDetector({formats:["ean_13","ean_8","code_128","upc_a","upc_e"]}),codes=await detector.detect(el.barcodeVideo);if(codes[0]?.rawValue)return handleBarcode(codes[0].rawValue)}catch(error){console.info("Barkod taraması bekliyor.")}if(session===cameraSession)scanFrame=requestAnimationFrame(()=>scanBarcode(session))}
function stopCamera(){cameraSession++;cancelAnimationFrame(scanFrame);scanFrame=0;if(cameraStream){cameraStream.getTracks().forEach(t=>t.stop());cameraStream=null}if(el.barcodeVideo)el.barcodeVideo.srcObject=null}
async function handleBarcode(raw){const code=String(raw||"").replace(/\s/g,"");if(code.length<4)return show("Geçerli barkod numarasını girin.");pendingBarcode=code;el.barcodeInput.value=code;const item=stocks.find(x=>x.active&&x.barcode===code);if(item){stopCamera();el.barcodeDialog.close();beep();if(barcodeMode==="search"||barcodeMode==="new"){if(el.productsDialog.open)el.productsDialog.close();openHistory(item.id);show(`${item.name} zaten stokta kayıtlı.`)}else{openEntry(item.id);show(`${item.name} bulundu.`)}return}if(barcodeMode==="new"){stopCamera();el.cameraStatus.textContent="Ürün bilgileri aranıyor…";await lookupNewProduct(code);return}if(barcodeMode==="search"){el.barcodeMessage.textContent=`${code} barkoduyla kayıtlı stok ürünü bulunamadı.`;el.barcodeProduct.closest("label").hidden=true;el.saveBarcodeButton.hidden=true;el.barcodeMatch.hidden=false;return}el.barcodeProduct.closest("label").hidden=false;el.saveBarcodeButton.hidden=false;el.barcodeMessage.textContent=`${code} barkodu henüz bir ürüne bağlı değil.`;const active=stocks.filter(x=>x.active).sort((a,b)=>a.name.localeCompare(b.name,"tr"));el.barcodeProduct.innerHTML='<option value="">Ürün seçin</option>'+active.map(x=>`<option value="${x.id}">${esc(x.name)}</option>`).join("");el.barcodeMatch.hidden=false;el.barcodeProduct.focus()}
async function lookupNewProduct(code){let product=null;const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),8000);try{const fields="code,product_name_tr,product_name,brands,quantity,image_front_small_url",response=await fetch(`https://world.openfoodfacts.org/api/v2/product/${encodeURIComponent(code)}.json?fields=${fields}`,{signal:controller.signal});if(response.ok){const data=await response.json();if(data.status===1)product=data.product||null}}catch(error){console.info("Harici ürün bilgisi alınamadı.")}finally{clearTimeout(timer)}el.barcodeDialog.close();setStockProductType("independent");el.independentBarcode.value=code;el.independentName.value=String(product?.product_name_tr||product?.product_name||"").trim();el.independentBrand.value=String(product?.brands||"").trim();el.independentImageUrl.value=String(product?.image_front_small_url||"");el.productLookupPreview.hidden=false;el.lookupProductTitle.textContent=el.independentName.value||"Ürün internette bulunamadı";el.lookupProductInfo.textContent=[el.independentBrand.value,product?.quantity].filter(Boolean).join(" • ")||"Ürün adını elle yazabilirsiniz.";if(el.independentImageUrl.value){el.lookupProductImage.src=el.independentImageUrl.value;el.lookupProductImage.hidden=false}else{el.lookupProductImage.removeAttribute("src");el.lookupProductImage.hidden=true}beep();setTimeout(()=>el.independentName.focus(),100);show(product?"Ürün bilgileri bulundu; kontrol edip kaydedin.":"Ürün bulunamadı; bilgileri elle tamamlayın.")}
async function saveBarcodeMatch(){const item=stocks.find(x=>x.id===el.barcodeProduct.value);if(!item||!pendingBarcode)return show("Barkodun bağlanacağı ürünü seçin.");if(stocks.some(x=>x.id!==item.id&&x.barcode===pendingBarcode))return show("Bu barkod başka bir ürüne bağlı.");el.saveBarcodeButton.disabled=true;try{await updateDoc(doc(stocksCol,item.id),{barcode:pendingBarcode,updatedAt:serverTimestamp(),updatedBy:auth.currentUser.uid});stopCamera();el.barcodeDialog.close();beep();openEntry(item.id);show(`${item.name} barkodla eşleştirildi.`)}catch(error){console.error(error);show("Barkod eşleştirilemedi.")}finally{el.saveBarcodeButton.disabled=false}}
function beep(){try{const C=window.AudioContext||window.webkitAudioContext,c=new C(),o=c.createOscillator(),g=c.createGain();o.frequency.value=880;g.gain.value=.05;o.connect(g);g.connect(c.destination);o.start();o.stop(c.currentTime+.08)}catch(error){}}

function normalizeStock(id,d){const units=Math.max(1,num(d.unitsPerPackage)||1),legacyUnitCost=d.purchasePriceBasis==="package"?num(d.purchasePrice)/units:d.purchasePriceBasis==="unit"?num(d.purchasePrice):0;return{id,name:String(d.name||"Ürün"),brand:String(d.brand||""),linkedMenuItemId:String(d.linkedMenuItemId||""),barcode:String(d.barcode||""),productImageUrl:String(d.productImageUrl||""),quantity:num(d.quantity),unit:String(d.unit||"adet"),unitsPerPackage:units,warningThreshold:num(d.warningThreshold),unitCost:num(d.unitCost)||legacyUnitCost,lastPurchaseTotal:num(d.lastPurchaseTotal),stockTrackingEnabled:d.stockTrackingEnabled!==false,automaticDeduction:d.automaticDeduction===true,active:d.active!==false}}
function timestamp(v){return v?.toMillis?.()||0}function num(v){return Number(v)||0}function displayUnit(v){const value=String(v||"");return value?value.charAt(0).toLocaleUpperCase("tr-TR")+value.slice(1).toLocaleLowerCase("tr-TR"):""}function today(){return new Intl.DateTimeFormat("en-CA",{timeZone:"Europe/Istanbul"}).format(new Date())}function formatDate(v){const[y,m,d]=String(v||"").split("-");return y&&m&&d?`${d}.${m}.${y}`:"—"}function formatNumber(v){return new Intl.NumberFormat("tr-TR",{maximumFractionDigits:2}).format(num(v))}function money(v){return new Intl.NumberFormat("tr-TR",{style:"currency",currency:"TRY",minimumFractionDigits:num(v)%1?2:0}).format(num(v))}function esc(v){return String(v??"").replace(/[&<>'"]/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;","'":"&#39;",'"':"&quot;"}[c]))}function updateClock(){const n=new Date();$("currentTime").textContent=new Intl.DateTimeFormat("tr-TR",{hour:"2-digit",minute:"2-digit",hour12:false,timeZone:"Europe/Istanbul"}).format(n);$("currentDate").textContent=new Intl.DateTimeFormat("tr-TR",{day:"2-digit",month:"2-digit",year:"2-digit",timeZone:"Europe/Istanbul"}).format(n).replace(/\./g,"/")}function show(message){clearTimeout(toastTimer);el.toast.textContent=message;el.toast.classList.add("show");toastTimer=setTimeout(()=>el.toast.classList.remove("show"),3000)}
